package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.notificaciones.*;import cl.nexbyte.siger.institucional.identidad.*;import cl.nexbyte.siger.institucional.robustez.*;
import java.time.*;import java.util.*;import java.nio.file.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;import static cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.*;
class TareasNotificacionesTest {
 @TempDir Path p;DatosAvisosTest x;
 @BeforeEach void start()throws Exception{x=new DatosAvisosTest(p);}@AfterEach void end(){x.close();}
 void denied(int n,org.junit.jupiter.api.function.Executable e){assertEquals(n,assertThrows(FalloTecnico.class,e).status);}
 @Test void tareasNacenDelCasoAbiertoYNoSeImponenAunqueSeaTiOJefatura(){UUID c=x.caso();denied(400,()->x.tareas.crear(x.a(x.prof),UUID.randomUUID(),new TareasPersonales.Edicion(0,"Título","",null,null,null,null,"NORMAL",null,null,null)));var e=x.edit(c,null,null);denied(403,()->x.tareas.crear(x.a(x.head),UUID.randomUUID(),new TareasPersonales.Edicion(0,e.titulo(),e.descripcion(),null,null,null,null,"NORMAL","CASO",c,x.prof)));denied(404,()->x.tareas.crear(x.a(x.otro),UUID.randomUUID(),e));denied(404,()->x.tareas.crear(x.a(x.ti),UUID.randomUUID(),e));assertEquals(0,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_task",Integer.class));}
 @Test void fechasSonIndependientesYConfirmacionManualNoCierraCasoNiCreaActuaciones(){UUID c=x.caso();var t=x.tareas.crear(x.a(x.prof),UUID.randomUUID(),x.edit(c,x.tiempo.instant().minusSeconds(1),x.tiempo.instant().plusSeconds(120)));var task=x.tareas.leer(x.a(x.prof),t.id());assertTrue(task.recordatorio().isBefore(task.ventanaDesde()));assertTrue(task.plazo().isAfter(task.ventanaHasta()));denied(400,()->x.tareas.estado(x.a(x.prof),UUID.randomUUID(),t.id(),new TareasPersonales.Cambio(0,"COMPLETADA",false)));x.tareas.estado(x.a(x.prof),UUID.randomUUID(),t.id(),new TareasPersonales.Cambio(0,"COMPLETADA",true));assertTrue(x.tareas.leer(x.a(x.prof),t.id()).confirmacionManual());assertEquals("EN_GESTION",x.core.caso(x.a(x.prof),c).estado());assertEquals(0,x.core.caso(x.a(x.prof),c).actuaciones().size());assertEquals(2,x.tareas.historial(x.a(x.prof),t.id()).size());}
 @Test void lecturaEsPersonalInclusoParaJefaturaTiYProfesionalMismaUnidad(){UUID c=x.caso();var t=x.tareas.crear(x.a(x.prof),UUID.randomUUID(),x.edit(c,null,null));denied(404,()->x.tareas.leer(x.a(x.head),t.id()));denied(404,()->x.tareas.leer(x.a(x.ti),t.id()));denied(404,()->x.tareas.leer(x.a(x.otro),t.id()));assertTrue(x.tareas.listar(x.a(x.head),"").isEmpty());}
 @Test void idempotenciaConflictoYFallosDePersistenciaSonAtomicos(){UUID c=x.caso(),key=UUID.randomUUID();var e=x.edit(c,null,null);var a=x.tareas.crear(x.a(x.prof),key,e);assertEquals(a,x.tareas.crear(x.a(x.prof),key,e));assertEquals(1,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM task_history",Integer.class));denied(409,()->x.tareas.crear(x.a(x.prof),key,new TareasPersonales.Edicion(0,"Otro","",null,null,null,null,"ALTA","CASO",c,null)));x.d.ddl(s->s.execute("ALTER TABLE task_history ADD CONSTRAINT test_history_block CHECK (snapshot_doc NOT LIKE '%BLOQUEO_HISTORIA%')"));try{assertThrows(org.springframework.dao.DataAccessException.class,()->x.tareas.crear(x.a(x.prof),UUID.randomUUID(),new TareasPersonales.Edicion(0,"BLOQUEO_HISTORIA","",null,null,null,null,"NORMAL","CASO",c,null)));}finally{x.d.ddl(s->s.execute("ALTER TABLE task_history DROP CONSTRAINT test_history_block"));}assertEquals(1,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_task",Integer.class));}
 @Test void temporalesNoSeDuplicanPorReinicioOEdicionDeTexto(){UUID c=x.caso();var t=x.tareas.crear(x.a(x.prof),UUID.randomUUID(),x.edit(c,x.tiempo.instant().minusSeconds(1),x.tiempo.instant().plusSeconds(60)));x.tareas.temporales();x.notices.proyectar();x.tareas.temporales();x.notices.proyectar();assertEquals(1,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_notification WHERE category='TAREA_RECORDATORIO'",Integer.class));var old=x.tareas.leer(x.a(x.prof),t.id());x.tareas.editar(x.a(x.prof),UUID.randomUUID(),t.id(),new TareasPersonales.Edicion(0,"Texto editado",old.descripcion(),old.recordatorio(),old.ventanaDesde(),old.ventanaHasta(),old.plazo(),"ALTA","CASO",c,null));new TareasPersonales(x.d.db,x.recursos,x.d.mapper,x.tiempo).temporales();x.notices.proyectar();assertEquals(1,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_notification WHERE category='TAREA_RECORDATORIO'",Integer.class));x.tiempo.avanzar(61);x.tareas.temporales();x.notices.proyectar();assertEquals(1,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_notification WHERE category='TAREA_VENCIDA'",Integer.class));}
 @Test void casoCerradoNoAdmiteNuevasTareasNiCambioDeCaso(){UUID c=x.caso(),c2=x.caso();var t=x.tareas.crear(x.a(x.prof),UUID.randomUUID(),x.edit(c,null,null));denied(409,()->x.tareas.editar(x.a(x.prof),UUID.randomUUID(),t.id(),x.edit(c2,null,null)));x.core.clasificar(x.a(x.head),UUID.randomUUID(),c,new Clasificacion(0,"BAJA","Fundamento sintético"));x.core.revisarCaso(x.a(x.prof),UUID.randomUUID(),c,new Decision(1,"Cierre sintético"),"CIERRE");denied(409,()->x.tareas.crear(x.a(x.prof),UUID.randomUUID(),x.edit(c,null,null)));x.tareas.estado(x.a(x.prof),UUID.randomUUID(),t.id(),new TareasPersonales.Cambio(0,"CANCELADA",false));assertEquals("CANCELADA",x.tareas.leer(x.a(x.prof),t.id()).estado());}
 @Test void nuevaComunicacionDistribucionYAsignacionResuelvenDestinatarioCorrecto(){UUID com=x.manual();x.notices.proyectar();assertEquals(1,x.notices.listar(x.a(x.dist),0,30).items().size());assertTrue(x.notices.listar(x.a(x.ti),0,30).items().isEmpty());x.core.distribuir(x.a(x.dist),UUID.randomUUID(),com,new Distribucion(0,List.of(new NuevoDestino("UPR","DEMO_SEDE_A",x.head))));x.notices.proyectar();assertTrue(x.notices.listar(x.a(x.head),0,30).items().stream().anyMatch(n->n.tipo().equals("DESTINO_PENDIENTE")));assertTrue(x.notices.listar(x.a(x.headOtra),0,30).items().isEmpty());var d=x.core.detalle(x.a(x.head),com).destinos().getFirst();x.core.abrirCaso(x.a(x.head),UUID.randomUUID(),d.id(),new Asignacion(0,x.prof,null));x.notices.proyectar();var n=x.notices.listar(x.a(x.prof),0,30).items().getFirst();assertEquals("CASO_ASIGNADO",n.tipo());assertTrue(n.ruta().startsWith("caso/"));denied(404,()->x.notices.leer(x.a(x.otro),n.id()));x.notices.leer(x.a(x.prof),n.id());assertEquals(0,x.notices.pendientes(x.a(x.prof)));}
 @Test void hijaYNuevoAntecedenteNoSeDifundenEntreUnidades(){UUID c=x.caso(),com=x.core.caso(x.a(x.prof),c).comunicacionId(),child=x.manual();x.core.vincular(x.a(x.dist),UUID.randomUUID(),child,new Vinculacion(com,c,"Antecedente sintético"));x.notices.proyectar();assertTrue(x.notices.listar(x.a(x.prof),0,30).items().stream().anyMatch(n->n.tipo().equals("ANTECEDENTE_NUEVO")));assertFalse(x.notices.listar(x.a(x.otro),0,30).items().stream().anyMatch(n->n.tipo().equals("ANTECEDENTE_NUEVO")));assertEquals(1,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_notification WHERE category='ANTECEDENTE_NUEVO'",Integer.class));}
 @Test void revisionesDerivacionesYReaperturasApuntanALaDecision(){UUID c=x.caso();x.core.revisarCaso(x.a(x.prof),UUID.randomUUID(),c,new Decision(0,"Revisión sintética"),"SOLICITUD_TERMINO");x.notices.proyectar();assertTrue(x.notices.listar(x.a(x.head),0,30).items().stream().anyMatch(n->n.tipo().equals("REVISION_TERMINO")));x.core.revisarCaso(x.a(x.head),UUID.randomUUID(),c,new Decision(1,"Continuar"),"DEVOLUCION");x.core.solicitarDerivacion(x.a(x.head),UUID.randomUUID(),c,new SolicitarDerivacion(2,"UPD","DEMO_SEDE_A","Motivo","Solo antecedentes sintéticos"));x.notices.proyectar();assertTrue(x.notices.listar(x.a(x.headOtra),0,30).items().stream().anyMatch(n->n.tipo().equals("DERIVACION_PENDIENTE")));assertTrue(x.notices.listar(x.a(x.ti),0,30).items().isEmpty());}
 @Test void revocacionYReasignacionImpidenVerAvisosYTareasPrevias(){UUID c=x.caso();var t=x.tareas.crear(x.a(x.prof),UUID.randomUUID(),x.edit(c,null,null));x.notices.proyectar();var id=x.notices.listar(x.a(x.prof),0,30).items().getFirst().id();var current=x.ids.cuentas(x.ti).stream().filter(u->u.id().equals(x.prof)).findFirst().orElseThrow();x.ids.revocar(x.ti,x.prof,current.asignaciones().getFirst().get("id").toString());assertTrue(x.notices.listar(x.a(x.prof),0,30).items().isEmpty());denied(404,()->x.tareas.leer(x.a(x.prof),t.id()));denied(404,()->x.notices.leer(x.a(x.prof),id));}
 @Test void noSePierdeEventoConSecuenciaMenorQueLosYaProcesados(){UUID c=x.caso();x.notices.proyectar();x.d.db.sql.update("DELETE FROM notification_source WHERE stream_code='CORE' AND event_key=(SELECT CONCAT('',MIN(seq)) FROM core_event WHERE code='CASO_ABIERTO')");x.d.db.sql.update("DELETE FROM notification_outbox WHERE notification_id IN (SELECT id FROM institution_notification WHERE category='CASO_ASIGNADO')");x.d.db.sql.update("DELETE FROM institution_notification WHERE category='CASO_ASIGNADO'");x.notices.proyectar();assertEquals(1,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_notification WHERE category='CASO_ASIGNADO' AND resource_id=?",Integer.class,c.toString()));}

 @Test void reasignarCasoNotificaAlNuevoResponsableSinTransferirTareaPersonal(){UUID c=x.caso();var t=x.tareas.crear(x.a(x.prof),UUID.randomUUID(),x.edit(c,null,null));x.notices.proyectar();String next=x.cuenta("prof.dos","UPR","DEMO_SEDE_A","PROFESIONAL","UNIDAD_SEDE");x.core.asignar(x.a(x.head),UUID.randomUUID(),c,new Asignacion(0,next,null));x.notices.proyectar();assertTrue(x.notices.listar(x.a(next),0,30).items().stream().anyMatch(n->n.tipo().equals("CASO_ASIGNADO")));assertFalse(x.notices.listar(x.a(x.prof),0,30).items().stream().anyMatch(n->n.tipo().equals("CASO_ASIGNADO")));denied(404,()->x.tareas.leer(x.a(next),t.id()));denied(404,()->x.tareas.leer(x.a(x.prof),t.id()));}
 @Test void reaperturaDirigeAvisoALaJefaturaDelCaso(){UUID c=x.caso();x.core.clasificar(x.a(x.head),UUID.randomUUID(),c,new Clasificacion(0,"BAJA","Fundamento sintético"));x.core.revisarCaso(x.a(x.prof),UUID.randomUUID(),c,new Decision(1,"Cierre sintético"),"CIERRE");UUID child=x.manual(),parent=x.core.caso(x.a(x.prof),c).comunicacionId();x.core.vincular(x.a(x.dist),UUID.randomUUID(),child,new Vinculacion(parent,c,"Antecedente sintético"));x.core.evaluarAntecedente(x.a(x.prof),UUID.randomUUID(),child,new EvaluarAntecedente(0,x.core.caso(x.a(x.prof),c).revision(),"ADMITIDA","Fundamento sintético"));x.core.solicitarReapertura(x.a(x.prof),UUID.randomUUID(),c,new SolicitarReapertura(x.core.caso(x.a(x.prof),c).revision(),List.of(child),"Nueva gestión sintética",null,null));x.notices.proyectar();assertTrue(x.notices.listar(x.a(x.head),0,30).items().stream().anyMatch(n->n.tipo().equals("REAPERTURA_PENDIENTE")));assertFalse(x.notices.listar(x.a(x.headOtra),0,30).items().stream().anyMatch(n->n.tipo().equals("REAPERTURA_PENDIENTE")));}

 @Test void distribucionNoAnulaLasFacultadesAdicionalesDeJefatura(){x.ids.otorgar(x.ti,x.head,new IdentidadInstitucional.Otorgar("DISTRIBUCION","INSTITUCION",null,null,x.tiempo.instant().minusSeconds(1),null));UUID c=x.caso();assertEquals(0,x.core.reaperturas(x.a(x.head),c,true,0,20).total());assertDoesNotThrow(()->x.core.caso(x.a(x.head),c));}
}
